const text = String(query.expression)
  .replace(/,/g, "")
  .trim();

if (!text) {
  return "No calculation expression was provided.";
}

try {
  const result = Function(
    `"use strict"; return (${text})`
  )();

  if (!Number.isFinite(result)) {
    return "The calculation did not produce a valid number.";
  }

  return String(result);

} catch (error) {
  return "I could not calculate that expression.";
}
